alter table public.role_assignments drop constraint if exists role_assignments_role_check;
alter table public.role_assignments add constraint role_assignments_role_check check(role in ('founder','admin','engineering','editorial','finance','advertising','moderation','support','analyst','contractor'));
alter table public.role_assignments add column if not exists scope text[] not null default '{}'::text[];alter table public.role_assignments add column if not exists expires_at timestamptz;alter table public.role_assignments add column if not exists granted_by uuid references auth.users(id) on delete set null;alter table public.role_assignments add column if not exists reason text;
create table if not exists public.buildpulse_workforce_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,worker_type text not null check(worker_type in ('employee','contractor','advisor')),department text,status text not null default 'invited' check(status in ('invited','active','suspended','ended')),require_mfa boolean not null default true,require_passkey boolean not null default true,locale text,time_zone text,last_access_review_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_workforce_audit_log(id bigint generated always as identity primary key,actor_user_id uuid references auth.users(id) on delete set null,action text not null,resource_type text,resource_id text,outcome text not null default 'success',ip_hash text,user_agent_hash text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.buildpulse_workforce_profiles enable row level security;alter table public.buildpulse_workforce_audit_log enable row level security;revoke all on public.buildpulse_workforce_profiles from anon,authenticated;revoke all on public.buildpulse_workforce_audit_log from anon,authenticated;grant all on public.buildpulse_workforce_profiles to service_role;grant all on public.buildpulse_workforce_audit_log to service_role;
create or replace function public.buildpulse_has_role(required_roles text[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.role_assignments r join public.buildpulse_workforce_profiles w on w.user_id=r.user_id where r.user_id=(select auth.uid()) and r.role=any(required_roles) and r.revoked_at is null and (r.expires_at is null or r.expires_at>now()) and w.status='active')$$;revoke all on function public.buildpulse_has_role(text[]) from public;grant execute on function public.buildpulse_has_role(text[]) to authenticated;